let state=null;const $=s=>document.querySelector(s);const esc=(v='')=>String(v).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
async function api(url,options={}){const r=await fetch(url,{headers:{'Content-Type':'application/json'},...options});const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.error||`HTTP ${r.status}`);return data}
async function init(){const me=await api('/api/admin/me');if(me.authenticated)await showApp()}
$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();$('#loginError').textContent='';try{await api('/api/admin/login',{method:'POST',body:JSON.stringify({login:$('#login').value,password:$('#password').value})});await showApp()}catch{$('#loginError').textContent='Неверный логин или пароль'}});
async function showApp(){$('#loginView').classList.add('hidden');$('#appView').classList.remove('hidden');state=await api('/api/settings');render()}
function field(label,path,value,textarea=false,full=false){return `<label class="field ${full?'full':''}">${esc(label)}${textarea?`<textarea data-path="${esc(path)}">${esc(value)}</textarea>`:`<input data-path="${esc(path)}" value="${esc(value)}">`}</label>`}
function render(){const s=state.site;$('#textFields').innerHTML=[field('Название проекта','site.brand',s.brand),field('Надпись над Hero','site.eyebrow',s.eyebrow),field('Главный заголовок','site.heroTitle',s.heroTitle),field('Текст Hero','site.heroText',s.heroText,true,true),field('Заголовок О проекте','site.aboutTitle',s.aboutTitle),field('Текст О проекте','site.aboutText',s.aboutText,true,true),field('Заголовок категорий','site.catalogTitle',s.catalogTitle),field('Описание категорий','site.catalogText',s.catalogText,true,true),field('Заголовок калькулятора','site.calculatorTitle',s.calculatorTitle),field('Описание калькулятора','site.calculatorText',s.calculatorText,true,true),field('Footer','site.footerText',s.footerText,true,true)].join('');
const labels={heroPrimary:'Hero / основная',heroSecondary:'Hero / вторичная',telegram:'Telegram'};$('#buttonFields').innerHTML=Object.entries(state.buttons).map(([key,b])=>`<div class="item-card" data-button="${esc(key)}"><h4>${esc(labels[key]||key)}</h4><div class="item-grid"><label class="mini">Текст<input data-bfield="text" value="${esc(b.text)}"></label><label class="mini">Ссылка<input data-bfield="url" value="${esc(b.url)}"></label><label class="check"><input type="checkbox" data-bfield="enabled" ${b.enabled!==false?'checked':''}>Показывать</label><label class="check"><input type="checkbox" data-bfield="newTab" ${b.newTab?'checked':''}>Новая вкладка</label></div></div>`).join('');
$('#linkFields').innerHTML=Object.entries(state.links).map(([k,v])=>field(k,`links.${k}`,v)).join('');$('#calculatorFields').innerHTML=[field('Валюта','calculator.currency',state.calculator.currency),field('Наценка, %','calculator.markupPercent',state.calculator.markupPercent),field('Минимальная сумма','calculator.minimumAmount',state.calculator.minimumAmount)].join('');renderCategories()}
function renderCategories(){$('#categoriesList').innerHTML=[...state.calculator.categories].sort((a,b)=>(a.order||0)-(b.order||0)).map(c=>{const i=state.calculator.categories.indexOf(c);return `<div class="item-card" data-cat-index="${i}"><div class="category-grid"><label class="mini">Название<input data-cfield="name" value="${esc(c.name)}"></label><label class="mini">ID<input data-cfield="id" value="${esc(c.id)}"></label><label class="mini">Цена<input type="number" min="0" data-cfield="price" value="${Number(c.price)||0}"></label><label class="mini">Порядок<input type="number" data-cfield="order" value="${Number(c.order)||0}"></label></div><div class="row-bottom"><label class="check"><input type="checkbox" data-cfield="enabled" ${c.enabled!==false?'checked':''}> Активна</label><button class="danger" data-delete-cat="${i}">УДАЛИТЬ</button></div></div>`}).join('')}
function setPath(obj,path,value){const p=path.split('.');let cur=obj;p.slice(0,-1).forEach(k=>cur=cur[k]);cur[p.at(-1)]=value}
document.addEventListener('input',e=>{if(e.target.dataset.path){const p=e.target.dataset.path,n=['calculator.markupPercent','calculator.minimumAmount'].includes(p);setPath(state,p,n?Number(e.target.value):e.target.value);if(p==='links.telegram'&&state.buttons.telegram)state.buttons.telegram.url=e.target.value}const card=e.target.closest('[data-button]');if(card&&e.target.dataset.bfield){const k=card.dataset.button,f=e.target.dataset.bfield;state.buttons[k][f]=e.target.type==='checkbox'?e.target.checked:e.target.value;if(k==='telegram'&&f==='url')state.links.telegram=e.target.value}const cat=e.target.closest('[data-cat-index]');if(cat&&e.target.dataset.cfield){const c=state.calculator.categories[Number(cat.dataset.catIndex)],f=e.target.dataset.cfield;c[f]=e.target.type==='checkbox'?e.target.checked:(['price','order'].includes(f)?Number(e.target.value):e.target.value)}});
document.addEventListener('click',e=>{const tab=e.target.closest('[data-tab]');if(tab){document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));tab.classList.add('active');document.querySelectorAll('.panel').forEach(x=>x.classList.remove('active-panel'));$(`#tab-${tab.dataset.tab}`).classList.add('active-panel');$('#pageTitle').textContent=tab.textContent}if(e.target.dataset.deleteCat!=null){const i=Number(e.target.dataset.deleteCat),c=state.calculator.categories[i];if(confirm(`Удалить категорию "${c.name}"?`)){state.calculator.categories.splice(i,1);renderCategories()}}});
$('#addCategoryBtn').addEventListener('click',()=>{const id=`category_${Math.random().toString(16).slice(2,8)}`;state.calculator.categories.push({id,name:'Новая категория',price:0,enabled:true,order:state.calculator.categories.length+1});renderCategories()});
$('#saveBtn').addEventListener('click',async()=>{$('#flash').textContent='Сохранение...';try{await api('/api/admin/settings',{method:'PUT',body:JSON.stringify(state)});$('#flash').textContent='Изменения сохранены'}catch(e){$('#flash').textContent=`Ошибка: ${e.message}`}});$('#logoutBtn').addEventListener('click',async()=>{await api('/api/admin/logout',{method:'POST'});location.reload()});init().catch(()=>{});
